mkdir -p /c/Temp/usageprobe-scripts && cat > /c/Temp/usageprobe-scripts/probe.js <<'EOF'
const { spawn } = require('child_process');
const fs = require('fs');
const cookies = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const evalFile = process.argv[3];
const url = process.argv[4] || 'https://claude.ai/settings/usage';
const edge = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const port = 9333;
const proc = spawn(edge, ['--headless=new', `--remote-debugging-port=${port}`, '--user-data-dir=C:/Temp/usageprobe/profile2', '--window-size=1200,800', '--no-first-run', 'about:blank'], { stdio: 'ignore' });
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  let targets;
  for (let i = 0; i < 40; i++) { try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); break; } catch { await sleep(250); } }
  const page = targets.find(t => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise(r => ws.onopen = r);
  let id = 0; const pending = {};
  ws.onmessage = m => { const d = JSON.parse(m.data); if (d.id && pending[d.id]) { pending[d.id](d); delete pending[d.id]; } };
  const send = (method, params = {}) => new Promise(r => { const i = ++id; pending[i] = r; ws.send(JSON.stringify({ id: i, method, params })); });
  await send('Network.enable');
  const ua = (await send('Runtime.evaluate', { expression: 'navigator.userAgent', returnByValue: true })).result.result.value.replace('HeadlessEdg', 'Edg');
  await send('Network.setUserAgentOverride', { userAgent: ua });
  for (const c of cookies) {
    await send('Network.setCookie', { name: c.Name, value: c.Value, domain: c.Domain, path: c.Path || '/', secure: !!c.IsSecure, httpOnly: !!c.IsHttpOnly, url: 'https://claude.ai' + (c.Path || '/') });
  }
  await send('Page.enable');
  await send('Page.navigate', { url });
  await sleep(9000);
  const expr = fs.readFileSync(evalFile, 'utf8');
  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
  console.log(typeof r.result.result.value === 'string' ? r.result.result.value : JSON.stringify(r.result, null, 1).slice(0, 4000));
  if (process.argv[5]) { const s = await send('Page.captureScreenshot'); fs.writeFileSync(process.argv[5], Buffer.from(s.result.data, 'base64')); }
  ws.close(); proc.kill();
  process.exit(0);
})().catch(e => { console.error(e); proc.kill(); process.exit(1); });
EOF
