(async () => {
  const out = [];
  out.push('URL ' + location.href + ' title=' + document.title);
  const bar = document.querySelector('[role=meter][aria-valuenow],[role=progressbar][aria-valuenow]');
  out.push('bar? ' + !!bar);
  let n = bar;
  while (n && n !== document.documentElement) {
    const cs = getComputedStyle(n);
    out.push(`${n.tagName} role=${n.getAttribute('role')||''} tabindex=${n.getAttribute('tabindex')||''} id=${n.id||''} class="${(n.className&&n.className.baseVal===undefined?n.className:'').slice(0,140)}" pos=${cs.position} disp=${cs.display} ovy=${cs.overflowY} h=${Math.round(n.getBoundingClientRect().height)} sh=${n.scrollHeight} maxh=${cs.maxHeight}`);
    n = n.parentElement;
  }
  const dialogs = document.querySelectorAll('[role=dialog]');
  out.push('dialogs ' + dialogs.length);
  for (const b of document.querySelectorAll('button[aria-label],button[data-testid]')) out.push('BTN aria=' + b.getAttribute('aria-label') + ' testid=' + b.getAttribute('data-testid') + ' text=' + (b.textContent||'').trim().slice(0,40));
  try { const r = await fetch('/api/account'); const j = await r.json(); out.push('api/account status ' + r.status + ' keys=' + Object.keys(j).join(',') + ' hasEmail=' + !!j.email_address); } catch (e) { out.push('api err ' + e); }
  return out.join('\n');
})()
