                _ = core.ExecuteScriptAsync(js);
#pragma warning restore VSTHRD110
            }
            catch (Exception ex)
            {
                Debug.WriteLine("ClaudeUsageControl: SwitchAccountButton_Click failed: " + ex);
            }
        }

