/* *******************************************************************************************************************
 * Application: ClaudeCodeExtension
 *
 * Autor:  Daniel Carvalho Liedke / Claude Code
 *
 * Copyright © Daniel Carvalho Liedke 2026
 * Usage and reproduction in any manner whatsoever without the written permission of Daniel Carvalho Liedke is strictly forbidden.
 *
 * Purpose: Native mode composer's usage button (ring + popup):
 *          - Context window figures come from the last completed turn's status line, per chat tab
 *          - Plan limits come from the cached Claude Usage snapshot, the same numbers the Claude Usage tab shows
 *          - Opening the popup refreshes the usage data in the background; the tab itself is only shown
 *            by "See detailed breakdown"
 *
 * *******************************************************************************************************************/

using ClaudeCodeVS.Agents;
using ClaudeCodeVS.UI;
using Microsoft.VisualStudio.Shell;
using Microsoft.VisualStudio.Threading;
using Newtonsoft.Json;
using System;
using System.Diagnostics;
using System.Globalization;
using System.Linq;
using System.Threading.Tasks;

namespace ClaudeCodeVS
{
    public partial class ClaudeCodeControl
    {
        // Status line of the panel's own chat's last completed turn. Parallel tabs keep theirs on NativeChatSessionState.
        private ClaudeStatusLineInput _mainStatusLine;

        // The refresh a ring click started; a second click while it runs waits on it instead of starting another.
        private JoinableTask _indicatorRefresh;

        // Longest the popup shows its refresh ring; the refresh itself keeps running past it.
        private const int UsageRefreshTextCapMs = 20000;

        // Completed by HandleScrapedSnapshot, so a ring click's refresh knows when the new figures are in.
        private TaskCompletionSource<bool> _indicatorScrapeTcs;

        /// <summary>Pushes the usage figures for one chat tab. <paramref name="session"/> is null for the panel's own chat.</summary>
        private void UpdateChatUsageIndicator(ChatTranscriptView transcript, NativeChatSessionState session, AiProvider? provider)
        {
            if (transcript == null)
            {
                return;
            }

            ClaudeStatusLineInput status = session != null ? session.LastStatusLine : _mainStatusLine;
            transcript.SetUsageIndicator(BuildChatUsageIndicatorData(provider, status));
        }

        /// <summary>
        /// Re-pushes the figures to every chat tab. Called when a new usage snapshot arrives, so an open popup
        /// updates in place, and when a chat is cleared.
        /// </summary>
        private void RefreshChatUsageIndicators()
        {
            ThreadHelper.ThrowIfNotOnUIThread();
            try
            {
                if (ChatTranscript != null)
                {
                    UpdateChatUsageIndicator(ChatTranscript, null, GetActiveOrSelectedProvider());
                }

                NativeChatSessionState[] sessions;
                lock (_sessionLock)
                {
                    sessions = _nativeSessions.Values.ToArray();
                }

                foreach (NativeChatSessionState session in sessions)
                {
                    UpdateChatUsageIndicator(session.ChatTranscript, session, session.SelectedProvider);
                }
            }
            catch (Exception ex)
            {
                Debug.WriteLine("RefreshChatUsageIndicators failed: " + ex.Message);
            }
        }

        /// <summary>
        /// The popup's contents. The button is only offered for Claude providers, the only ones with a context
        /// window in the status line and a Claude Usage snapshot.
        /// </summary>
        private ChatUsageIndicatorData BuildChatUsageIndicatorData(AiProvider? provider, ClaudeStatusLineInput status)
        {
            var data = new ChatUsageIndicatorData { Visible = IsClaudeProvider(provider) };
            if (!data.Visible)
            {
                return data;
            }

            if (status != null && status.HasCurrentUsage && status.ContextWindowSize > 0)
            {
                // The CLI measures the window from the input side only; the last turn's output does not count.
                long tokens = (long)status.InputTokens + status.CacheCreationTokens + status.CacheReadTokens;
                data.HasContext = true;
                data.ContextTokens = tokens;
                data.ContextWindow = status.ContextWindowSize;
                data.ContextPercent = ChatUsageIndicator.ContextPercent(tokens, status.ContextWindowSize);
            }

            UsageSnapshot snap = ReadCachedUsageSnapshot();
            if (snap != null)
            {
                data.HasPlanUsage = true;
                data.SessionLabel = snap.SessionLabel ?? string.Empty;
                data.SessionPercent = ChatUsageIndicator.ClampPercent(snap.SessionPercent);
                data.SessionReset = snap.SessionReset ?? string.Empty;
                data.ShowWeekly = !snap.NoWeeklyLimit;
                data.WeeklyPercent = ChatUsageIndicator.ClampPercent(snap.WeeklyPercent);
                data.WeeklyReset = snap.WeeklyReset ?? string.Empty;
                data.ShowExtra = snap.HasExtraUsage && !string.IsNullOrEmpty(snap.ExtraUsageSpent);
                data.ExtraPercent = ChatUsageIndicator.ClampPercent(snap.ExtraUsagePercent);
                data.ExtraSpent = snap.ExtraUsageSpent ?? string.Empty;
                data.ExtraReset = snap.ExtraUsageReset ?? string.Empty;
                data.AccountEmail = snap.AccountEmail ?? string.Empty;
            }

            data.UpdatedText = FormatUsageUpdatedText(snap != null ? _settings?.LastUsageTimestamp : null);
            return data;
        }

        private UsageSnapshot ReadCachedUsageSnapshot()
        {
            if (string.IsNullOrEmpty(_settings?.LastUsageJson))
            {
                return null;
            }

            try
            {
                return JsonConvert.DeserializeObject<UsageSnapshot>(_settings.LastUsageJson);
            }
            catch (Exception ex)
            {
                Debug.WriteLine("ReadCachedUsageSnapshot failed: " + ex.Message);
                return null;
            }
        }

        /// <summary>"Updated 2:15 PM", or "Not updated since 2:15 PM" once the snapshot is stale; empty without one.</summary>
        private static string FormatUsageUpdatedText(string lastUsageTimestamp)
        {
            if (string.IsNullOrEmpty(lastUsageTimestamp))
            {
                return string.Empty;
            }

            if (!DateTime.TryParse(lastUsageTimestamp, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out DateTime stamp))
            {
                return string.Empty;
            }

            string time = stamp.ToLocalTime().ToString("t", CultureInfo.CurrentCulture);
            return IsUsageSnapshotStale(lastUsageTimestamp, DateTime.UtcNow)
                ? Loc.L("Not updated since {0}", time)
                : Loc.L("Updated {0}", time);
        }

        /// <summary>
        /// Ring click: the popup opens and the usage data refreshes behind it. The account guard comes first,
        /// as in the background timer. A visible tab is reloaded in place; a hidden one is scraped off-screen,
        /// so the tab is never shown by this path. The popup shows a rotating ring until the refresh is over.
        /// </summary>
        private void OnComposerUsageRequested(object sender, EventArgs e)
        {
            ThreadHelper.ThrowIfNotOnUIThread();

            if (_indicatorRefresh == null || _indicatorRefresh.IsCompleted)
            {
#pragma warning disable VSSDK007 // Joined below by every click waiting on it
                _indicatorRefresh = ThreadHelper.JoinableTaskFactory.RunAsync(RefreshUsageForIndicatorAsync);
#pragma warning restore VSSDK007
            }

            JoinableTask refresh = _indicatorRefresh;
            var transcript = sender as ChatTranscriptView;
#pragma warning disable VSSDK007 // Fire-and-forget is intentional here
            ThreadHelper.JoinableTaskFactory.RunAsync(async delegate
            {
                try
                {
                    // Capped: a slow rebuild of the off-screen page can take over a minute, and the popup
                    // should not keep its ring spinning that long. Figures that land later still update it.
                    await Task.WhenAny(refresh.JoinAsync(), Task.Delay(UsageRefreshTextCapMs));
                }
                finally
                {
                    await ThreadHelper.JoinableTaskFactory.SwitchToMainThreadAsync();
                    transcript?.EndUsageRefresh();
                }
            }).FileAndForget("claudecode/usage/indicator");
#pragma warning restore VSSDK007
        }

        private async Task RefreshUsageForIndicatorAsync()
        {
            await ThreadHelper.JoinableTaskFactory.SwitchToMainThreadAsync();
            var scraped = new TaskCompletionSource<bool>();
            _indicatorScrapeTcs = scraped;
            try
            {
                // A switch handled here means the page was signed out and the user is asked to sign in again.
                if (await SyncUsageWithClaudeAccountAsync())
                {
                    return;
                }

                // A visible tab's reload returns at once; wait for the page to post the new figures.
                // The off-screen path below already waits for them itself.
                var control = _usageToolWindow?.UsageControl;
                if (_usageToolWindow?.IsWindowVisible == true && control != null)
                {
                    if (control.Reload())
                    {
#pragma warning disable VSTHRD003 // scraped is completed by HandleScrapedSnapshot on the UI thread; no cross-context deadlock
                        await Task.WhenAny(scraped.Task, Task.Delay(15000));
#pragma warning restore VSTHRD003
                    }
                    return;
                }

                await EnsureUsageToolWindowAsync(showWindow: false, updateWindowState: false, activate: false);
            }
            catch (Exception ex)
            {
                Debug.WriteLine("RefreshUsageForIndicatorAsync failed: " + ex);
            }
            finally
            {
                if (_indicatorScrapeTcs == scraped)
                {
                    _indicatorScrapeTcs = null;
                }
            }
        }

        /// <summary>"See detailed breakdown": shows the Claude Usage tab, exactly as the inline bars' click does.</summary>
        private void OnComposerUsageDetailsRequested(object sender, EventArgs e)
        {
            ThreadHelper.ThrowIfNotOnUIThread();

#pragma warning disable VSSDK007 // Fire-and-forget is intentional here
            ThreadHelper.JoinableTaskFactory.RunAsync(() => EnsureUsageToolWindowAsync(showWindow: true)).FileAndForget("claudecode/usage/details");
#pragma warning restore VSSDK007
        }
    }
}

/* *******************************************************************************************************************
 * Application: ClaudeCodeExtension
 *
 * Autor:  Daniel Carvalho Liedke / Claude Code
 *
 * Copyright © Daniel Carvalho Liedke 2026
 * Usage and reproduction in any manner whatsoever without the written permission of Daniel Carvalho Liedke is strictly forbidden.
 *
 * Purpose: Display values and ring geometry for the native-mode composer's usage button and its popup (pure, unit-tested)
 *
 * *******************************************************************************************************************/

using System;
using System.Globalization;
using System.Text;
using System.Windows;
using System.Windows.Media;

namespace ClaudeCodeVS.UI
{
    /// <summary>
    /// Everything the composer's usage popup shows, already reduced to display values. The parent control
    /// fills it from the chat's own status line (context) and the cached Claude Usage snapshot (plan limits).
    /// </summary>
    public sealed class ChatUsageIndicatorData
    {
        /// <summary>false hides the button: only Claude providers have a context window and plan limits.</summary>
        public bool Visible { get; set; }

        /// <summary>false until a turn has reported the context window (none before the first turn, or after Clear Chat).</summary>
        public bool HasContext { get; set; }
        public long ContextTokens { get; set; }
        public int ContextWindow { get; set; }
        public int ContextPercent { get; set; }

        /// <summary>false until the Claude Usage tab has produced a snapshot.</summary>
        public bool HasPlanUsage { get; set; }
        public string SessionLabel { get; set; } = string.Empty;
        public int SessionPercent { get; set; }
        public string SessionReset { get; set; } = string.Empty;
        public bool ShowWeekly { get; set; }
        public int WeeklyPercent { get; set; }
        public string WeeklyReset { get; set; } = string.Empty;
        public bool ShowExtra { get; set; }
        public int ExtraPercent { get; set; }
        public string ExtraSpent { get; set; } = string.Empty;
        public string ExtraReset { get; set; } = string.Empty;

        /// <summary>"Updated 2:15 PM" or "Not updated since 2:15 PM"; empty when there is no snapshot.</summary>
        public string UpdatedText { get; set; } = string.Empty;

        /// <summary>E-mail of the claude.ai account the plan limits belong to; empty when unknown.</summary>
        public string AccountEmail { get; set; } = string.Empty;
    }

    /// <summary>Pure formatting and geometry behind the usage button; no WPF elements are created here.</summary>
    public static class ChatUsageIndicator
    {
        /// <summary>"413.9k", "1M", "1.2M", "950" — the figures the status line gives, shortened the way the CLI shows them.</summary>
        public static string FormatTokens(long tokens)
        {
            if (tokens < 0) tokens = 0;

            // From 999,950 up the thousands would round to "1000k", so the million unit takes over there.
            if (tokens >= 999950)
            {
                return Math.Round(tokens / 1000000.0, 1).ToString("0.#", CultureInfo.InvariantCulture) + "M";
            }

            if (tokens >= 1000)
            {
                return Math.Round(tokens / 1000.0, 1).ToString("0.#", CultureInfo.InvariantCulture) + "k";
            }

            return tokens.ToString(CultureInfo.InvariantCulture);
        }

        /// <summary>Share of the window in use, 0-100. Input-side tokens only, as the CLI computes it. 0 when the window is unknown.</summary>
        public static int ContextPercent(long tokens, int window)
        {
            if (window <= 0 || tokens <= 0) return 0;

            double percent = Math.Min(100.0, tokens * 100.0 / window);
            return (int)Math.Round(percent, MidpointRounding.AwayFromZero);
        }

        /// <summary>"413.9k / 1M (41%)"; just the token count when the window size is unknown.</summary>
        public static string ContextLine(long tokens, int window)
        {
            if (window <= 0)
            {
                return FormatTokens(tokens);
            }

            return FormatTokens(tokens) + " / " + FormatTokens(window) + " (" + ContextPercent(tokens, window) + "%)";
        }

        /// <summary>Clamps a percentage to 0-100 (the usage page can report more for extra usage, which has its own bar).</summary>
        public static int ClampPercent(int value)
        {
            return value < 0 ? 0 : (value > 100 ? 100 : value);
        }

        /// <summary>"41% used · Resets in 2 h"; blank details are skipped, so a missing reset leaves just the percentage.</summary>
        public static string PlanRowText(int percent, params string[] details)
        {
            string text = Loc.L("{0}% used", ClampPercent(percent));
            if (details == null)
            {
                return text;
            }

            foreach (string detail in details)
            {
                string clean = StripIconGlyphs(detail).Trim();
                if (clean.Length > 0)
                {
                    text += " · " + clean;
                }
            }

            return text;
        }

        /// <summary>
        /// Drops Private Use Area characters: claude.ai draws some icons with an icon font, and a snapshot
        /// scraped before the page filter existed can hold one where the reset text belongs (a box in VS).
        /// </summary>
        public static string StripIconGlyphs(string text)
        {
            if (string.IsNullOrEmpty(text))
            {
                return string.Empty;
            }

            var sb = new StringBuilder(text.Length);
            foreach (char c in text)
            {
                if (c < '' || c > '')
                {
                    sb.Append(c);
                }
            }

            return sb.ToString();
        }

        /// <summary>
        /// The ring's arc for <paramref name="fraction"/> (0-1) of a circle centred on
        /// (<paramref name="center"/>, <paramref name="center"/>), starting at 12 o'clock and running clockwise.
        /// Null when there is nothing to draw. A full circle stops just short of closing: an arc whose start and
        /// end coincide is not drawn at all.
        /// </summary>
        public static PathGeometry RingArc(double fraction, double center, double radius)
        {
            if (double.IsNaN(fraction) || fraction <= 0) return null;

            double sweep = Math.Min(fraction, 0.9999);
            var figure = new PathFigure
            {
                StartPoint = new Point(center, center - radius),
                IsClosed = false
            };
            figure.Segments.Add(new ArcSegment(
                ArcPoint(sweep, center, radius),
                new Size(radius, radius),
                0,
                sweep > 0.5,
                SweepDirection.Clockwise,
                true));

            var geometry = new PathGeometry();
            geometry.Figures.Add(figure);
            geometry.Freeze();
            return geometry;
        }

        /// <summary>The point <paramref name="fraction"/> of the way round a clockwise circle that starts at 12 o'clock.</summary>
        public static Point ArcPoint(double fraction, double center, double radius)
        {
            double angle = 2 * Math.PI * fraction;
            return new Point(center + radius * Math.Sin(angle), center - radius * Math.Cos(angle));
        }
    }
