30	    public partial class ClaudeCodeControl
31	    {
32	        // Status line of the panel's own chat's last completed turn. Parallel tabs keep theirs on NativeChatSessionState.
33	        private ClaudeStatusLineInput _mainStatusLine;
34	
35	        // The refresh a ring click started; a second click while it runs waits on it instead of starting another.
36	        private JoinableTask _indicatorRefresh;
37	
38	        // Longest the popup shows its refresh ring; the refresh itself keeps running past it.
39	        private const int UsageRefreshTextCapMs = 20000;
40	
41	        // Completed by HandleScrapedSnapshot, so a ring click's refresh knows when the new figures are in.
42	        private TaskCompletionSource<bool> _indicatorScrapeTcs;
