44	        /// <summary>Pushes the usage figures for one chat tab. <paramref name="session"/> is null for the panel's own chat.</summary>
45	        private void UpdateChatUsageIndicator(ChatTranscriptView transcript, NativeChatSessionState session, AiProvider? provider)
46	        {
47	            if (transcript == null)
48	            {
49	                return;
50	            }
51	
52	            ClaudeStatusLineInput status = session != null ? session.LastStatusLine : _mainStatusLine;
53	            transcript.SetUsageIndicator(BuildChatUsageIndicatorData(provider, status));
54	        }
55	
56	        /// <summary>
57	        /// Re-pushes the figures to every chat tab. Called when a new usage snapshot arrives, so an open popup
58	        /// updates in place, and when a chat is cleared.
59	        /// </summary>
60	        private void RefreshChatUsageIndicators()
61	        {
62	            ThreadHelper.ThrowIfNotOnUIThread();
63	            try
64	            {
65	                if (ChatTranscript != null)
66	                {
67	                    UpdateChatUsageIndicator(ChatTranscript, null, GetActiveOrSelectedProvider());
68	                }
69	
70	                NativeChatSessionState[] sessions;
71	                lock (_sessionLock)
72	                {
73	                    sessions = _nativeSessions.Values.ToArray();
74	                }
75	
76	                foreach (NativeChatSessionState session in sessions)
77	                {
78	                    UpdateChatUsageIndicator(session.ChatTranscript, session, session.SelectedProvider);
79	                }
80	            }
81	            catch (Exception ex)
82	            {
83	                Debug.WriteLine("RefreshChatUsageIndicators failed: " + ex.Message);
84	            }
85	        }
86	
87	        /// <summary>
88	        /// The popup's contents. The button is only offered for Claude providers, the only ones with a context
89	        /// window in the status line and a Claude Usage snapshot.
90	        /// </summary>
91	        private ChatUsageIndicatorData BuildChatUsageIndicatorData(AiProvider? provider, ClaudeStatusLineInput status)
92	        {
93	            var data = new ChatUsageIndicatorData { Visible = IsClaudeProvider(provider) };
94	            if (!data.Visible)
95	            {
96	                return data;
97	            }
98	
99	            if (status != null && status.HasCurrentUsage && status.ContextWindowSize > 0)
100	            {
101	                // The CLI measures the window from the input side only; the last turn's output does not count.
102	                long tokens = (long)status.InputTokens + status.CacheCreationTokens + status.CacheReadTokens;
103	                data.HasContext = true;
104	                data.ContextTokens = tokens;
105	                data.ContextWindow = status.ContextWindowSize;
106	                data.ContextPercent = ChatUsageIndicator.ContextPercent(tokens, status.ContextWindowSize);
107	            }
108	
109	            UsageSnapshot snap = ReadCachedUsageSnapshot();
110	            if (snap != null)
111	            {
112	                data.HasPlanUsage = true;
113	                data.SessionLabel = snap.SessionLabel ?? string.Empty;
114	                data.SessionPercent = ChatUsageIndicator.ClampPercent(snap.SessionPercent);
115	                data.SessionReset = snap.SessionReset ?? string.Empty;
116	                data.ShowWeekly = !snap.NoWeeklyLimit;
117	                data.WeeklyPercent = ChatUsageIndicator.ClampPercent(snap.WeeklyPercent);
118	                data.WeeklyReset = snap.WeeklyReset ?? string.Empty;
119	                data.ShowExtra = snap.HasExtraUsage && !string.IsNullOrEmpty(snap.ExtraUsageSpent);
120	                data.ExtraPercent = ChatUsageIndicator.ClampPercent(snap.ExtraUsagePercent);
121	                data.ExtraSpent = snap.ExtraUsageSpent ?? string.Empty;
122	                data.ExtraReset = snap.ExtraUsageReset ?? string.Empty;
123	                data.AccountEmail = snap.AccountEmail ?? string.Empty;
124	            }
125	
126	            data.UpdatedText = FormatUsageUpdatedText(snap != null ? _settings?.LastUsageTimestamp : null);
127	            return data;
128	        }
