130	        private UsageSnapshot ReadCachedUsageSnapshot()
131	        {
132	            if (string.IsNullOrEmpty(_settings?.LastUsageJson))
133	            {
134	                return null;
135	            }
136	
137	            try
138	            {
139	                return JsonConvert.DeserializeObject<UsageSnapshot>(_settings.LastUsageJson);
140	            }
141	            catch (Exception ex)
142	            {
143	                Debug.WriteLine("ReadCachedUsageSnapshot failed: " + ex.Message);
144	                return null;
145	            }
146	        }
147	
148	        /// <summary>"Updated 2:15 PM", or "Not updated since 2:15 PM" once the snapshot is stale; empty without one.</summary>
149	        private static string FormatUsageUpdatedText(string lastUsageTimestamp)
150	        {
151	            if (string.IsNullOrEmpty(lastUsageTimestamp))
152	            {
153	                return string.Empty;
154	            }
155	
156	            if (!DateTime.TryParse(lastUsageTimestamp, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out DateTime stamp))
157	            {
158	                return string.Empty;
159	            }
160	
161	            string time = stamp.ToLocalTime().ToString("t", CultureInfo.CurrentCulture);
162	            return IsUsageSnapshotStale(lastUsageTimestamp, DateTime.UtcNow)
163	                ? Loc.L("Not updated since {0}", time)
164	                : Loc.L("Updated {0}", time);
165	        }
