167	        /// <summary>
168	        /// Ring click: the popup opens and the usage data refreshes behind it. The account guard comes first,
169	        /// as in the background timer. A visible tab is reloaded in place; a hidden one is scraped off-screen,
170	        /// so the tab is never shown by this path. The popup shows a rotating ring until the refresh is over.
171	        /// </summary>
172	        private void OnComposerUsageRequested(object sender, EventArgs e)
173	        {
174	            ThreadHelper.ThrowIfNotOnUIThread();
175	
176	            if (_indicatorRefresh == null || _indicatorRefresh.IsCompleted)
177	            {
178	#pragma warning disable VSSDK007 // Joined below by every click waiting on it
179	                _indicatorRefresh = ThreadHelper.JoinableTaskFactory.RunAsync(RefreshUsageForIndicatorAsync);
180	#pragma warning restore VSSDK007
181	            }
182	
183	            JoinableTask refresh = _indicatorRefresh;
184	            var transcript = sender as ChatTranscriptView;
185	#pragma warning disable VSSDK007 // Fire-and-forget is intentional here
186	            ThreadHelper.JoinableTaskFactory.RunAsync(async delegate
187	            {
188	                try
189	                {
190	                    // Capped: a slow rebuild of the off-screen page can take over a minute, and the popup
191	                    // should not keep its ring spinning that long. Figures that land later still update it.
192	                    await Task.WhenAny(refresh.JoinAsync(), Task.Delay(UsageRefreshTextCapMs));
193	                }
194	                finally
195	                {
196	                    await ThreadHelper.JoinableTaskFactory.SwitchToMainThreadAsync();
197	                    transcript?.EndUsageRefresh();
198	                }
199	            }).FileAndForget("claudecode/usage/indicator");
200	#pragma warning restore VSSDK007
201	        }
202	
203	        private async Task RefreshUsageForIndicatorAsync()
204	        {
205	            await ThreadHelper.JoinableTaskFactory.SwitchToMainThreadAsync();
206	            var scraped = new TaskCompletionSource<bool>();
207	            _indicatorScrapeTcs = scraped;
208	            try
209	            {
210	                // A switch handled here means the page was signed out and the user is asked to sign in again.
211	                if (await SyncUsageWithClaudeAccountAsync())
212	                {
213	                    return;
214	                }
215	
216	                // A visible tab's reload returns at once; wait for the page to post the new figures.
217	                // The off-screen path below already waits for them itself.
218	                var control = _usageToolWindow?.UsageControl;
219	                if (_usageToolWindow?.IsWindowVisible == true && control != null)
220	                {
221	                    if (control.Reload())
222	                    {
223	#pragma warning disable VSTHRD003 // scraped is completed by HandleScrapedSnapshot on the UI thread; no cross-context deadlock
224	                        await Task.WhenAny(scraped.Task, Task.Delay(15000));
225	#pragma warning restore VSTHRD003
226	                    }
227	                    return;
228	                }
229	
230	                await EnsureUsageToolWindowAsync(showWindow: false, updateWindowState: false, activate: false);
231	            }
232	            catch (Exception ex)
233	            {
234	                Debug.WriteLine("RefreshUsageForIndicatorAsync failed: " + ex);
235	            }
236	            finally
237	            {
238	                if (_indicatorScrapeTcs == scraped)
239	                {
240	                    _indicatorScrapeTcs = null;
241	                }
242	            }
243	        }
244	
245	        /// <summary>"See detailed breakdown": shows the Claude Usage tab, exactly as the inline bars' click does.</summary>
246	        private void OnComposerUsageDetailsRequested(object sender, EventArgs e)
247	        {
248	            ThreadHelper.ThrowIfNotOnUIThread();
249	
250	#pragma warning disable VSSDK007 // Fire-and-forget is intentional here
251	            ThreadHelper.JoinableTaskFactory.RunAsync(() => EnsureUsageToolWindowAsync(showWindow: true)).FileAndForget("claudecode/usage/details");
252	#pragma warning restore VSSDK007
253	        }
254	    }
255	}
